        RBinPlugin *plugin = bin->force? r_bin_get_binplugin_by_name (bin, bin->force): NULL;
        if (plugin) {
                return plugin;
        }

        plugin = pluginname? r_bin_get_binplugin_by_name (bin, pluginname): NULL;
        if (plugin) {
                return plugin;
